/**
 * ADR-117 data-driven sound bank: event key -> files/variants/bus/limits (bank.json, generated by
 * scripts/gen-audio-bank.mjs). Pure: resolution, format choice and variant picking are unit-tested without WebAudio.
 */
export type BusName = "master" | "music" | "ambient" | "sfx" | "ui" | "voice";
export const BUSES: readonly BusName[] = ["master", "music", "ambient", "sfx", "ui", "voice"];
export type AudioFormat = "ogg" | "opus" | "m4a" | "mp3";
export interface SynthSpec { r: string; f: number; len: number }
export interface SoundDef {
  bus: Exclude<BusName, "master">; files?: string[]; volume: number; pitchJitter: number; volumeJitter: number; loop: boolean;
  stream?: boolean; priority: number; maxVoices: number; synth?: SynthSpec;
  /** Distance (tiles) at which a positional sound is inaudible; default 18. */ maxDist?: number;
}
export interface SoundBankJson { version: number; basePath: string; formats: AudioFormat[]; sounds: Record<string, SoundDef> }
export interface Resolved { key: string; def: SoundDef; /** Index into def.files (-1 = synth placeholder). */ variant: number; urls: string[]; pitch: number; gain: number }

const MIME: Record<AudioFormat, string> = { ogg: 'audio/ogg; codecs="vorbis"', opus: 'audio/ogg; codecs="opus"', m4a: 'audio/mp4; codecs="mp4a.40.2"', mp3: "audio/mpeg" };
/** Formats the browser can play, in bank preference order (ogg/opus first, m4a/mp3 fallback for Safari). */
export function playableFormats(prefs: readonly AudioFormat[], canPlay: (mime: string) => string): AudioFormat[] {
  const ok = prefs.filter((f) => { try { return canPlay(MIME[f]) !== ""; } catch { return false; } });
  return ok.length ? ok : [...prefs];
}

export class SoundBank {
  private last = new Map<string, number>();
  constructor(readonly json: SoundBankJson, private formats: AudioFormat[] = json.formats, private rng: () => number = Math.random) {}
  setFormats(f: AudioFormat[]): void { this.formats = f; }
  /** Exact key, then dotted parents ("footstep.grass.run" -> "footstep.grass" -> "footstep"); undefined = fail silently. */
  lookup(key: string): { key: string; def: SoundDef } | undefined {
    for (let k = key; k; k = k.includes(".") ? k.slice(0, k.lastIndexOf(".")) : "") { const def = this.json.sounds[k]; if (def) return { key: k, def }; }
    return undefined;
  }
  has(key: string): boolean { return this.lookup(key) !== undefined; }
  keys(): string[] { return Object.keys(this.json.sounds); }
  /** Candidate URLs for one file in format preference order. */
  urlsFor(file: string, base = ""): string[] { return this.formats.map((f) => `${base}${this.json.basePath}${file}.${f}`); }
  /** Pick a variant (no immediate repeat when >1) and randomized pitch/gain. */
  resolve(key: string, base = ""): Resolved | undefined {
    const hit = this.lookup(key); if (!hit) return undefined;
    const { def } = hit; const n = def.files?.length ?? 0; let variant = -1;
    if (n > 0) { variant = Math.floor(this.rng() * n) % n; const prev = this.last.get(hit.key); if (n > 1 && variant === prev) variant = (variant + 1) % n; this.last.set(hit.key, variant); }
    const pitch = 1 + (this.rng() * 2 - 1) * def.pitchJitter;
    const gain = Math.max(0, def.volume * (1 + (this.rng() * 2 - 1) * def.volumeJitter));
    return { key: hit.key, def, variant, urls: variant >= 0 ? this.urlsFor(def.files![variant]!, base) : [], pitch, gain };
  }
}
